import{_ as o,o as e,c as s,am as t}from"./chunks/framework._FJXuPhs.js";const d=JSON.parse('{"title":"使用 Postman 增强 swagger 功能","description":"","frontmatter":{"title":"使用 Postman 增强 swagger 功能","excerpt":"摘要","date":"2025-05-25 19:43:38","updated":"2025-05-25 19:43:38"},"headers":[],"relativePath":"框架/工具类框架/框架-Swagger/使用 Postman 增强 swagger 功能.md","filePath":"框架/工具类框架/框架-Swagger/使用 Postman 增强 swagger 功能.md","lastUpdated":null}'),n={name:"框架/工具类框架/框架-Swagger/使用 Postman 增强 swagger 功能.md"};function l(i,a,r,p,c,g){return e(),s("div",null,[...a[0]||(a[0]=[t('<h3 id="postman简介" tabindex="-1">Postman简介 <a class="header-anchor" href="#postman简介" aria-label="Permalink to &quot;Postman简介&quot;">​</a></h3><p>Postman是一款API接口调试工具，使用它可以很方便的对接口进行测试，并且后端人员可以将自己的调试结果导出，方便前端人员调试。</p><h3 id="postman的安装及设置" tabindex="-1">Postman的安装及设置 <a class="header-anchor" href="#postman的安装及设置" aria-label="Permalink to &quot;Postman的安装及设置&quot;">​</a></h3><ul><li>在Postman官网下载安装包安装即可，下载地址：<a href="https://www.getpostman.com/downloads/" target="_blank" rel="noreferrer">https://www.getpostman.com/downloads/</a></li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250525194415.png" alt="image.png"></p><ul><li>这里不得不说，Postman的界面还是做的很好的，比起Swagger来说好多了，Postman默认提供了两种主题，一种亮色和一种暗色，可以通过左上角的<code>File-&gt;Settings</code>按钮打开。</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250525194424.png" alt="image.png"></p><ul><li>可能界面默认的字体大小并不适合你，尤其是大屏幕的电脑，可以在<code>View</code>下的<code>Zoom In</code>和<code>Zoom Out</code>按钮进行放大和缩小。</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250525194430.png" alt="image.png"></p><h3 id="swagger结合postman使用" tabindex="-1">Swagger结合Postman使用 <a class="header-anchor" href="#swagger结合postman使用" aria-label="Permalink to &quot;Swagger结合Postman使用&quot;">​</a></h3><p>下面介绍下如何将Swagger API导入到Postman中去，然后使用Postman来调试接口。</p><h4 id="swagger-api导入postman" tabindex="-1">Swagger API导入Postman <a class="header-anchor" href="#swagger-api导入postman" aria-label="Permalink to &quot;Swagger API导入Postman&quot;">​</a></h4><ul><li>首先我们需要启动使用了Swagger的应用项目，这里以之前的<code>mall-tiny-swagger</code>项目为例子，找到<code>api-docs</code>路径，访问地址：<a href="http://localhost:8088/swagger-ui/" target="_blank" rel="noreferrer">http://localhost:8088/swagger-ui/</a></li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250525194506.png" alt="image.png"></p><ul><li>什么是Swagger的<code>api-docs</code>访问路径？该路径会返回JSON格式数据，应用中Swagger渲染API文档页面的所有数据就是来源于此，Postman也是可以通过这些数据来渲染API文档页面，这里的<code>api-docs</code>地址为：<a href="http://localhost:8088/v2/api-docs" target="_blank" rel="noreferrer">http://localhost:8088/v2/api-docs</a></li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250525194533.png" alt="image.png"></p><ul><li>在postman中点击<code>import</code>按钮，选择<code>Link</code>，输入Swagger的<code>api-docs</code>路径即可将Swagger生成的接口导入到Postman中去了；</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250525194542.png" alt="image.png"></p><ul><li>直接使用默认选项导入即可，无需修改；</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250525194551.png" alt="image.png"></p><ul><li>导入成功后，Swagger中的接口就会出现在Postman中了，之后就只需要在Postman中改改参数就可以开始调试接口了，是不是很方便！</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250525194559.png" alt="image.png"></p><h4 id="postman设置环境变量" tabindex="-1">Postman设置环境变量 <a class="header-anchor" href="#postman设置环境变量" aria-label="Permalink to &quot;Postman设置环境变量&quot;">​</a></h4><ul><li>我们随意找个接口访问下，会发现访问出错了，那是因为<code>baseUrl</code>这个环境变量设置有问题，导致了接口无法访问；</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250525194708.png" alt="image.png"></p><ul><li>我们只要在Postman中设置<code>baseUrl</code>这个环境变量，就可以正常访问了；</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250525194714.png" alt="image.png"></p><ul><li>添加好环境变量之后，需要选择好环境才会被应用。</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250525194719.png" alt="image.png"></p><h4 id="postman访问添加登录认证" tabindex="-1">Postman访问添加登录认证 <a class="header-anchor" href="#postman访问添加登录认证" aria-label="Permalink to &quot;Postman访问添加登录认证&quot;">​</a></h4><ul><li><p>这时候再次访问接口会发现我们的接口需要登录认证才能正常访问；</p></li><li><p>我们可以先调用登录接口来获取Token；</p></li><li><p>给需要登录认证的接口添加<code>Bearer Token</code>类型的Token，我们可以发现需要配置一个叫<code>token</code>的环境变量；</p></li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250525194742.png" alt="image.png"></p><ul><li><p>在环境变量中添加<code>token</code>；</p></li><li><p>添加完环境变量后即可正常访问需要登录认证的接口了。</p></li></ul><h3 id="postman的缺点" tabindex="-1">Postman的缺点 <a class="header-anchor" href="#postman的缺点" aria-label="Permalink to &quot;Postman的缺点&quot;">​</a></h3><p>此种方法使用Postman来调试接口是非常强大的，但是对于文档展示能力有点偏弱。</p><ul><li>比如说Swagger中的接口对于请求和返回参数都有非常完善的注释信息；</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250525194810.png" alt="image.png"></p><ul><li>而在Postman中，这些文档信息得不到体现，Postman毕竟还只是一个接口调试工具。</li></ul><h3 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h3><p>Swagger和Postman结合使用比较好，Swagger用来看接口文档信息，Postman用于调试，</p><p>将Swagger中的接口导入到Postman中可以弥补Swagger在接口调试方面的不足。</p>',41)])])}const u=o(n,[["render",l]]);export{d as __pageData,u as default};
